cd /tmp/ross-work/main && python3 - <<'PY'
import subprocess, datetime, re

branches=['rachel','monica','phoebe','joey','chandler','ross']
speaker={'rachel':'Rachel','monica':'Monica','phoebe':'Phoebe','joey':'Joey','chandler':'Chandler','ross':'Ross'}

def branch_of(sha):
    for b in branches:
        out=subprocess.check_output(['git','-C','/tmp/ross-work/ross','log','--format=%H',f'origin/friend/{b}'],text=True).split()
        if sha in out:
            return b
    return None

commits=[]
for b in branches:
    out=subprocess.check_output(['git','-C','/tmp/ross-work/ross','log','--format=%H',f'origin/friend/{b}'],text=True).split()
    for sha in out:
        body=subprocess.check_output(['git','-C','/tmp/ross-work/ross','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' not in body:
            continue
        ep=''
        for line in body.splitlines():
            if line.startswith('Episode:'):
                ep=line.split(':',1)[1].strip()
        if ep!='S07/E10':
            continue
        ci=subprocess.check_output(['git','-C','/tmp/ross-work/ross','show','-s','--format=%cI',sha],text=True).strip()
        dt=datetime.datetime.fromisoformat(ci.replace('Z','+00:00'))
        ts=dt.astimezone(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        commits.append((sha,branch_of(sha),ts,body.rstrip('\n'),ci))

text=open('S07/E10.md').read()
existing=set(re.findall(r'Source: friend/\w+ @ ([0-9a-f]+)',text))
missing=[c for c in commits if c[0] not in existing]
missing.sort(key=lambda c:(c[4],c[0]))

with open('S07/E10.md','a') as f:
    for sha,branch,ts,body,ci in missing:
        f.write('\n')
        f.write(f'**{speaker[branch]}** ({ts})\n\n')
        f.write(f'Source: friend/{branch} @ {sha}\n\n')
        f.write(body + '\n')
print('appended',len(missing))
for c in missing: print(c[2],c[1],c[0])
